input.newString:
['Paz também é uma missão','Por um tempo, não há alarmes nem chamados urgentes. O que fazer com esse raro silêncio?','Visitar quem você ama|+5 bond,-8 ryo','Pesquisar uma técnica nova|+4 ninjutsu,+2 chakra,-6 ryo','Descansar sem culpa|+15 energy,+2 bond']];}
function nextEvent(){const pool=eventPool();let idx=Math.floor(Math.random()*pool.length);if(pool.length>1&&idx===state.eventIndex)idx=(idx+1)%pool.length;state.eventIndex=idx;const e=pool[idx];return{title:e[0],text:e[1],choices:e.slice(2).map(s=>{const [label,effect]=s.split('|');return{label,effect}})};}
const actions=[
{icon:'◈',title:'Treinar',hint:'Aprimore uma habilidade',run(){const skills=['taijutsu','ninjutsu','chakra'];const sk=skills[Math.floor(Math.random()*skills.length)];state[sk]+=5;state.energy-=14;return `Treino intenso: +5 ${skillLabel(sk)}.`}},
{icon:'⌕',title:'Estudar',hint:'Conhecimento e estratégia',run(){state.intel+=5;state.energy-=7;return'Você estudou táticas e teoria ninja. +5 inteligência.'}},
{icon:'♡',title:'Conviver',hint:'Fortaleça uma amizade',run(){let r=state.relations[Math.floor(Math.random()*state.relations.length)];r.value=clamp(r.value+9);state.bond+=3;state.energy-=4;return`Um bom momento com ${r.name}. +9 amizade.`}},
{icon:'⚑',title:'Fazer missão',hint:state.age<12?'A partir dos 12 anos':'Ganhe ryō e reputação',run(){if(state.age<12)return null;let success=state.intel+state.taijutsu+state.ninjutsu+state.chakra>150;state.ryo+=success?28:12;state.renown+=success?5:2;state.energy-=22;if(!success)state.health=state.health||100;return success?'Missão concluída com mérito. +28 ryō, +5 reputação.':'A missão foi complicada, mas voltou em segurança. +12 ryō, +2 reputação.'}},
{icon:'⌂',title:'Descansar',hint:'Recupere energia',run(){state.energy=clamp(state.energy+27);state.bond+=1;return'Um dia tranquilo devolveu suas forças. +27 energia.'}},
{icon:'◉',title:'Explorar',hint:'Descubra algo inesperado',run(){const finds=['Você ouviu histórias de viajantes. +2 inteligência.','Um comerciante pagou por sua ajuda. +18 ryō.','Encontrou um lugar calmo para meditar. +4 chakra.','Ajudou um morador e ganhou sua confiança. +3 reputação.'];let n=Math.floor(Math.random()*finds.length);if(n===0)state.intel+=2;if(n===1)state.ryo+=18;if(n===2)state.chakra+=4;if(n===3)state.renown+=3;state.energy-=5;return finds[n]}}
];
function doAction(i){if(state.finished||state.activities>=2||state.energy<5){toast(state.activities>=2?'Você já aproveitou suas duas atividades deste ano.':'Energia baixa — tente descansar.');return}const result=actions[i].run();if(!result){toast('Missões ninja ficam disponíveis a partir dos 12 anos.');return}state.activities++;state.energy=clamp(state.energy);state.ryo=Math.max(0,state.ryo);addJournal(result);save();render();toast(result)}
function applyEffect(effect){for(const part of effect.split(',')){const m=part.match(/^([+-])(\d+)\s+(\w+)$/);if(!m)continue;const amount=Number(m[2])*(m[1]==='-'?-1:1),key=m[3];if(key==='ryo')state.ryo=Math.max(0,state.ryo+amount);else if(key==='energy')state.energy=clamp(state.energy+amount);else if(key==='bond'){state.bond=clamp(state.bond+amount);if(state.relations.length)state.relations[0].value=clamp(state.relations[0].value+Math.ceil(amount/2))}else state[key]=clamp((state[key]||0)+amount)} }
function choose(i){const c=state.event.choices[i];applyEffect(c.effect);addJournal(`${state.event.title}: ${c.label}.`);state.activities=0;state.age++;if(state.age===13)state.phase='Genin';if(state.age===16)state.phase='Chūnin';if(state.age===20)state.phase='Jōnin';if(state.age===65)state.phase='Ancião';if(state.age>=85){state.finished=true;state.phase='Lenda';}state.energy=clamp(state.energy+8);state.event=state.finished?null:nextEvent();save();render();}
function stat(label,key,color=''){let value=clamp(state[key]);return `<div class="stat"><div class="stat-label"><span>${label}</span><b>${value}</b></div><div class="bar ${color}"><i style="width:${value}%"></i></div></div>`}
function render(){if(!state)return;$('#setup').classList.add('hidden');$('#game').classList.remove('hidden');const initials=state.name.slice(0,1).toUpperCase();const stage=state.age<12?'Academia Ninja':state.age<18?'Equipe Genin':state.age<30?'Shinobi de carreira':state.age<60?'Veterano':'Legado ninja';
$('#game').innerHTML=`<div class="game-header"><div><div class="eyebrow">${state.village} · ${state.clan}</div><h1 class="game-title">A vida de ${state.name}</h1><p class="subtitle">${stage} · ${state.phase}</p></div><div class="year-badge">Ano ${state.year+1} da jornada</div></div>${state.finished?`<div class="panel ending"><div class="eyebrow">Fim de uma jornada extraordinária</div><h2>${state.name}, uma vida lembrada</h2><p>Aos ${state.age} anos, você deixa um legado de ${state.renown} pontos de reputação. As histórias de seus feitos continuarão inspirando a próxima geração.</p><button class="primary" onclick="newLife()">Começar outra vida&nbsp; →</button></div>`:`<div class="layout"><div class="left-column"><article class="panel story"><div class="story-top"><span class="story-tag">Capítulo ${state.year+1} · ${state.age} anos</span><span class="tiny">${state.phase}</span></div><h2>${state.event.title}</h2><p>${state.event.text}</p><div class="choices">${state.event.choices.map((c,i)=>`<button class="choice" onclick="choose(${i})"><span>${c.label}</span><span class="arrow">→</span></button>`).join('')}</div><footer>Uma escolha por ano · As consequências moldam sua história</footer></article>
<div class="panel activities"><div class="section-head"><h3 class="section-title">O que você faz este ano?</h3><span class="counter">${state.activities}/2 atividades</span></div><div class="activity-grid">${actions.map((a,i)=>`<button class="activity" onclick="doAction(${i})" ${state.activities>=2||state.energy<5?'disabled':''}><span class="icon">${a.icon}</span><strong>${a.title}</strong><small>${a.title==='Fazer missão'&&state.age<12?'Desbloqueia aos 12 anos':a.hint}</small></button>`).join('')}</div><div class="year-control"><span class="year-note">Avançar sem fazer mais atividades também é uma escolha.</span><button class="finish-year" onclick="skipActivities()">${state.activities<2?'Pular atividades':'Pronto para seguir'} →</button></div></div>
<div class="panel journal-panel"><div class="section-head"><h3 class="section-title">Memórias recentes</h3><span class="counter">Diário</span></div><div class="journal-list">${state.journal.length?state.journal.slice(0,4).map(j=>`<div class="journal-item"><time>${j.age}a</time><span>${j.text}</span></div>`).join(''):'<div class="tiny">Suas escolhas importantes aparecerão aqui.</div>'}</div></div></div>
<aside class="right-column"><div class="panel stats-panel"><div class="profile"><div class="avatar">${initials}</div><div><div class="profile-name">${state.name}</div><div class="profile-sub">${state.clan} · ${state.phase}</div></div></div><div class="stats-grid">${stat('Chakra','chakra','blue')}${stat('Taijutsu','taijutsu','red')}${stat('Ninjutsu','ninjutsu','blue')}${stat('Inteligência','intel')}${stat('Vínculos','bond','green')}${stat('Reputação','renown','green')}</div><div class="resources"><div class="resource">Energia<b>${state.energy} / 100</b></div><div class="resource">Ryō<b>¥ ${state.ryo}</b></div></div></div>
<div class="panel rel-panel"><div class="section-head"><h3 class="section-title">Seu círculo</h3><span class="counter">Laços</span></div><div class="rel-list">${state.relations.map(r=>`<div class="rel"><div class="rel-face">${r.face}</div><div class="rel-info"><div class="rel-name">${r.name}</div><div class="rel-role">${r.role}</div></div><div class="rel-meter"><i style="width:${r.value}%"></i></div></div>`).join('')}</div></div><div style="display:flex;justify-content:space-between;align-items:center;padding:0 2px"><span class="tiny">Progresso salvo automaticamente</span><button class="secondary" style="padding:7px 10px;font-size:11px" onclick="confirmRestart()">Nova vida</button></div></aside></div>`;state.year=state.age-6;}
function skipActivities(){toast('Você segue para o próximo capítulo. Escolha um caminho!')}
function newLife(){localStorage.removeItem('shinobi-save');state=null;$('#game').classList.add('hidden');$('#setup').classList.remove('hidden');makeSetup();window.scrollTo(0,0)}
function confirmRestart(){if(confirm('Começar uma nova vida? Seu progresso atual será substituído.'))newLife()}
</script></body></html>

